    'How it works' => 'यह कैसे काम करता है',
    '• "Accept" and "Reject" have equal weight; the analytics switch is off by default (KVKK Cookie Guide / GDPR).' => '• "स्वीकार करें" और "अस्वीकार करें" का वज़न बराबर है; एनालिटिक्स स्विच डिफ़ॉल्ट रूप से बंद है (KVKK कुकी गाइड / GDPR)।',
    '• The visitor\'s choice is kept for 180 days and can be changed anytime via the "Cookie Preferences" footer link.' => '• विज़िटर की पसंद 180 दिन तक रखी जाती है और फ़ुटर के "कुकी प्राथमिकताएँ" लिंक से कभी भी बदली जा सकती है।',
    '• Google Analytics: ' => '• Google Analytics: ',
    'not set' => 'सेट नहीं',
    'Consent version: ' => 'सहमति संस्करण: ',
    '• Empty text fields use the built-in translation for each language.' => '• खाली टेक्स्ट फ़ील्ड हर भाषा का अंतर्निहित अनुवाद उपयोग करते हैं।',
    'Banner Texts' => 'बैनर पाठ',
    'Policy Link (defaults to Privacy Notice page)' => 'नीति लिंक (डिफ़ॉल्ट: गोपनीयता सूचना पेज)',
    'If you changed the texts or how cookies are used, you can show the banner again to visitors who already decided.' => 'यदि आपने पाठ या कुकी के उपयोग का तरीका बदला है, तो आप उन विज़िटरों को बैनर फिर से दिखा सकते हैं जो पहले ही निर्णय ले चुके हैं।',
    'Show the cookie banner to all visitors again?' => 'कुकी बैनर सभी विज़िटरों को फिर से दिखाएँ?',
    'Show again' => 'फिर से दिखाएँ',
