    '“%s” is being previewed in your browser only; the site has not changed for visitors.' => '“%s” का पूर्वावलोकन केवल आपके ब्राउज़र में हो रहा है; विज़िटरों के लिए साइट नहीं बदली है।',
    '“%s” was applied on %s. If you don’t like it, revert to the previous look in one click.' => '“%s” को %s को लागू किया गया। पसंद न आए तो एक क्लिक में पिछले रूप पर लौटें।',
    'Revert the site to the look it had before this template?' => 'साइट को इस टेम्पलेट से पहले वाले रूप पर लौटाएँ?',
