    'Remove %s (%s) from the site? Visitors can no longer choose this language.' => '%s (%s) को साइट से हटाएँ? विज़िटर अब यह भाषा नहीं चुन पाएँगे।',
    'Page names and URL slugs for this language are managed in' => 'इस भाषा के पेज नाम और URL स्लग यहाँ प्रबंधित होते हैं:',
    'Settings › URL Management' => 'सेटिंग्स › URL प्रबंधन',
    '.' => '.',
    'Security check failed (CSRF). Reload the page and try again.' => 'सुरक्षा जाँच विफल (CSRF)। पेज पुनः लोड करें और फिर प्रयास करें।',
    'Contact page texts saved.' => 'संपर्क पेज के पाठ सहेजे गए।',
    'Kicker' => 'उपशीर्ष पंक्ति',
    'Response note' => 'उत्तर नोट',
    'Contact Page' => 'संपर्क पेज',
    'The texts visitors read on the contact page. Layout and look are in Design.' => 'वे पाठ जो विज़िटर संपर्क पेज पर पढ़ते हैं। लेआउट और रूप डिज़ाइन में हैं।',
    'The contact page is currently off; texts are saved but not shown on the site.' => 'संपर्क पेज अभी बंद है; पाठ सहेजे जाते हैं पर साइट पर नहीं दिखते।',
    'Email' => 'ईमेल',
    'Shown on the page; form notifications also go here. Phone is in Design › Contact.' => 'पेज पर दिखता है; फ़ॉर्म सूचनाएँ भी यहीं आती हैं। फ़ोन डिज़ाइन › संपर्क में है।',
    'Logo' => 'लोगो',
    'Pages & Features' => 'पेज और सुविधाएँ',
    'URL Management' => 'URL प्रबंधन',
    'Privacy' => 'गोपनीयता',
    'Integrations' => 'इंटीग्रेशन',
    'Account & Backup' => 'खाता और बैकअप',
    'Site-wide settings. Use “Themes” for page layouts and the Content section in the sidebar for content.' => 'पूरी साइट की सेटिंग्स। पेज लेआउट के लिए “थीम” और सामग्री के लिए साइडबार का सामग्री खंड उपयोग करें।',
    'Settings sections' => 'सेटिंग्स खंड',
    'Show source language alongside' => 'स्रोत भाषा साथ में दिखाएँ',
    'Copy empty fields from %s' => 'खाली फ़ील्ड %s से कॉपी करें',
    'Auto-translate empty fields (%s → %s)' => 'खाली फ़ील्ड का स्वतः अनुवाद (%s → %s)',
    'Translating…' => 'अनुवाद हो रहा है…',
    '%d fields filled. Remember to save.' => '%d फ़ील्ड भरे गए। सहेजना न भूलें।',
    'No empty fields to fill.' => 'भरने के लिए कोई खाली फ़ील्ड नहीं।',
    'The translation service could not be reached. Try again shortly.' => 'अनुवाद सेवा तक पहुँचा नहीं जा सका। थोड़ी देर में फिर प्रयास करें।',
    'The source language is selected.' => 'स्रोत भाषा चुनी हुई है।',
    'All fields filled' => 'सभी फ़ील्ड भरे हुए',
    '%d of %d fields filled' => '%d / %d फ़ील्ड भरे हुए',
    'Editing language' => 'संपादन भाषा',
    'Source' => 'स्रोत',
    'Content language' => 'सामग्री भाषा',
    'No %s translation' => '%s अनुवाद नहीं है',
    '%s: %d of %d fields filled' => '%s: %d / %d फ़ील्ड भरे हुए',
    'Translation' => 'अनुवाद',
    'Missing %s' => 'अनुपलब्ध: %s',
    'Panel' => 'पैनल',
    'Visitors' => 'विज़िटर',
    'Design' => 'डिज़ाइन',
    'CONTENT' => 'सामग्री',
    'VISITORS' => 'विज़िटर',
    'DESIGN' => 'डिज़ाइन',
    'SETTINGS' => 'सेटिंग्स',
    'Panel language' => 'पैनल भाषा',
    'Changes only the panel’s menus and buttons. Content language is chosen from the bar at the top of each editor.' => 'केवल पैनल के मेनू और बटन बदलता है। सामग्री भाषा हर एडिटर के ऊपर की पट्टी से चुनी जाती है।',
    'Privacy & KVKK Settings' => 'गोपनीयता और KVKK सेटिंग्स',
    'Section pages' => 'खंड पेज',
    '13. Sidebar List' => '13. साइडबार सूची',
    'Numbered project list on the left, one large uncropped photo on the right; hovering the list switches the photo. Best for a few strong projects.' => 'बाईं ओर क्रमांकित प्रोजेक्ट सूची, दाईं ओर एक बड़ी बिना काटी तस्वीर; सूची पर होवर करने से तस्वीर बदलती है। कुछ सशक्त प्रोजेक्ट्स के लिए सर्वोत्तम।',
    '14. Archive by Year' => '14. वर्ष अनुसार आर्काइव',
    'Projects grouped under year headings with thumbnail, title and place. Best for a long, multi-project archive.' => 'प्रोजेक्ट्स वर्ष शीर्षकों के तहत थंबनेल, शीर्षक और स्थान के साथ समूहित। कई प्रोजेक्ट्स वाले लंबे आर्काइव के लिए सर्वोत्तम।',
    '15. Contact Sheet' => '15. कॉन्टैक्ट शीट',
    'All works as small numbered frames on black, like a film contact sheet; frames enlarge on hover. Best for many works.' => 'सभी काम काले पर छोटे क्रमांकित फ़्रेम के रूप में, फ़िल्म कॉन्टैक्ट शीट की तरह; होवर करने पर फ़्रेम बड़े होते हैं। बहुत से कामों के लिए सर्वोत्तम।',
    '16. Photo + Statement' => '16. तस्वीर + वक्तव्य',
    'One large photo on one side, a short statement in large type and the project list on the other. The text comes from the site description in Site Settings › General.' => 'एक तरफ़ बड़ी तस्वीर, दूसरी तरफ़ बड़े अक्षरों में छोटा वक्तव्य और प्रोजेक्ट सूची। पाठ साइट सेटिंग्स › सामान्य में साइट विवरण से आता है।',
    '17. Project Map' => '17. प्रोजेक्ट नक्शा',
    'Each project as a point on a world map where it was shot; clicking shows the cover and link. Project list alongside. Places are found from each project’s Location field.' => 'हर प्रोजेक्ट विश्व मानचित्र पर उस जगह एक बिंदु जहाँ वह शूट हुआ; क्लिक करने पर कवर और लिंक दिखता है। साथ में प्रोजेक्ट सूची। स्थान हर प्रोजेक्ट के स्थान फ़ील्ड से लिए जाते हैं।',
    '18. Sectioned Showcase' => '18. खंडों वाला शोकेस',
    'Full-screen cover, then Selected Work cards, latest blog posts (if blog is on), a short intro and About / Contact links. Everything on one page.' => 'फ़ुल-स्क्रीन कवर, फिर चयनित काम के कार्ड, नवीनतम ब्लॉग पोस्ट (यदि ब्लॉग चालू है), छोटा परिचय और परिचय / संपर्क लिंक। सब कुछ एक पेज पर।',
    '20. Thumbnail Grid' => '20. थंबनेल ग्रिड',
    'All work as small thumbnails side by side; titles on hover. Looks best with the sidebar menu. Columns and cropping are chosen on the Templates page.' => 'सभी काम छोटे थंबनेल के रूप में साथ-साथ; शीर्षक होवर पर। साइडबार मेनू के साथ सबसे अच्छा दिखता है। कॉलम और क्रॉपिंग टेम्पलेट्स पेज पर चुने जाते हैं।',
    '21. Photobook Spreads' => '21. फ़ोटोबुक स्प्रेड',
    'Work laid out as two-page book spreads on warm paper; the first page shows the site name and description. Page by page on phones.' => 'काम गर्म काग़ज़ पर दो-पृष्ठ पुस्तक स्प्रेड के रूप में; पहला पृष्ठ साइट का नाम और विवरण दिखाता है। फ़ोन पर पृष्ठ-दर-पृष्ठ।',
    '22. Mosaic Wall' => '22. मोज़ेक दीवार',
    'Covers of varying sizes form a dense wall; titles on hover. Columns are chosen on the Templates page.' => 'अलग-अलग आकार के कवर एक घनी दीवार बनाते हैं; शीर्षक होवर पर। कॉलम टेम्पलेट्स पेज पर चुने जाते हैं।',
    '23. Photo Wall' => '23. फ़ोटो दीवार',
    'Photos stacked uncropped in columns at their natural proportions, titles below. Set the column count in Themes › Customise › Homepage. Best for: series that mix portrait and landscape photos.' => 'तस्वीरें बिना काटे कॉलम में अपने प्राकृतिक अनुपात में, शीर्षक नीचे। कॉलम संख्या थीम › कस्टमाइज़ › होमपेज में सेट करें। सर्वोत्तम: ऐसी सीरीज़ जिनमें पोर्ट्रेट और लैंडस्केप दोनों तस्वीरें हों।',
    '24. Staggered Gallery' => '24. स्टैगर्ड गैलरी',
    'Uncropped photos in varying widths and offsets with generous space. Best for: calm selections that should feel like a gallery wall.' => 'बिना काटी तस्वीरें अलग-अलग चौड़ाई और ऑफ़सेट में, खुली जगह के साथ। सर्वोत्तम: शांत चयन जो गैलरी की दीवार जैसा लगे।',
    '25. One Large, Two Small' => '25. एक बड़ी, दो छोटी',
    'Blocks of three: one large and two small photos, the large one alternating sides. Best for: projects with strong cover photos.' => 'तीन-तीन के ब्लॉक: एक बड़ी और दो छोटी तस्वीरें, बड़ी तस्वीर बारी-बारी से तरफ़ बदलती है। सर्वोत्तम: सशक्त कवर तस्वीरों वाले प्रोजेक्ट्स।',
    '26. Featured + Grid' => '26. विशेष + ग्रिड',
    'The first work large and uncropped, then small square thumbnails. Best for: when you want to lead with one recent work.' => 'पहला काम बड़ा और बिना काटा, फिर छोटे वर्गाकार थंबनेल। सर्वोत्तम: जब आप किसी एक हालिया काम को आगे रखना चाहें।',
    '27. Zigzag Stream' => '27. ज़िगज़ैग प्रवाह',
    'Uncropped photos flow down the page, alternating left and right, titles below. Best for: strong single frames worth a long look.' => 'बिना काटी तस्वीरें पेज पर नीचे बहती हैं, बारी-बारी बाएँ और दाएँ, शीर्षक नीचे। सर्वोत्तम: सशक्त एकल फ़्रेम जो देर तक देखने लायक हों।',
    '28. Split Screens' => '28. स्प्लिट स्क्रीन',
    'Each project fills a screen: photo on one half, title and short text on the other, sides alternating. Choose edge-to-edge or framed (magazine) style.' => 'हर प्रोजेक्ट एक स्क्रीन भरता है: आधे पर तस्वीर, दूसरे आधे पर शीर्षक और छोटा पाठ, तरफ़ें बारी-बारी। किनारे-से-किनारे या फ़्रेमयुक्त (पत्रिका) शैली चुनें।',
    '29. Three Panels' => '29. तीन पैनल',
    'The screen splits into three tall panels, each a project cover with its name centred. Stacked on phones. Best for: portfolios with three to six main projects.' => 'स्क्रीन तीन लंबे पैनलों में बँटती है, हर एक प्रोजेक्ट कवर जिसका नाम बीच में हो। फ़ोन पर ऊपर-नीचे। सर्वोत्तम: तीन से छह मुख्य प्रोजेक्ट्स वाले पोर्टफ़ोलियो।',
    '30. Section Banners' => '30. खंड बैनर',
    'Each menu section becomes a wide banner with a cover photo, large title and an arrow. Shows sections on the homepage and projects on project lists.' => 'मेनू का हर खंड कवर तस्वीर, बड़े शीर्षक और तीर के साथ एक चौड़ा बैनर बन जाता है। होमपेज पर खंड और प्रोजेक्ट सूचियों में प्रोजेक्ट्स दिखाता है।',
    '31. Light Table' => '31. लाइट टेबल',
    'One large photo with a vertical thumbnail strip on the right; click a thumbnail (or use the arrow keys) to change the photo. On phones the strip moves below. Best for: showing photos one at a time on a dark background.' => 'एक बड़ी तस्वीर जिसके दाईं ओर ऊर्ध्वाधर थंबनेल पट्टी हो; तस्वीर बदलने के लिए थंबनेल पर क्लिक करें (या तीर कुंजियाँ उपयोग करें)। फ़ोन पर पट्टी नीचे चली जाती है। सर्वोत्तम: गहरी पृष्ठभूमि पर एक-एक करके तस्वीरें दिखाने के लिए।',
    '19. Free Collage' => '19. मुक्त कोलाज',
    'Photos placed freely in varied sizes and positions without a grid; titles appear on hover. Single column on phones. For artistic and personal work.' => 'तस्वीरें बिना ग्रिड के अलग-अलग आकार और स्थिति में स्वतंत्र रूप से रखी गईं; शीर्षक होवर पर दिखते हैं। फ़ोन पर एक कॉलम। कलात्मक और निजी काम के लिए।',
    'You have unsaved changes' => 'आपके बिना सहेजे बदलाव हैं',
    'Discard' => 'रद्द करें',
    'Unlisted' => 'असूचीबद्ध',
    'View on site' => 'साइट पर देखें',
    'Save (Ctrl+S)' => 'सहेजें (Ctrl+S)',
    'Homepage slide' => 'होमपेज स्लाइड',
    'Site settings / design' => 'साइट सेटिंग्स / डिज़ाइन',
    'CSRF security verification failed.' => 'CSRF सुरक्षा सत्यापन विफल।',
    'All page names, URL slugs, and top menu links have been updated.' => 'सभी पेज नाम, URL स्लग और शीर्ष मेनू लिंक अपडेट हो गए।',
    'Customize page names and permalinks. Changes automatically sync across panel templates, sidebars, and public navigation.' => 'पेज नाम और परमालिंक कस्टमाइज़ करें। बदलाव पैनल टेम्पलेट, साइडबार और सार्वजनिक नेविगेशन में अपने आप सिंक हो जाते हैं।',
    'Select Language to Edit:' => 'संपादन के लिए भाषा चुनें:',
    '1. Portfolio Main Name & Categories' => '1. पोर्टफ़ोलियो का मुख्य नाम और श्रेणियाँ',
    'Changing the Portfolio main name will automatically update all templates and panel sidebar links.' => 'पोर्टफ़ोलियो का मुख्य नाम बदलने से सभी टेम्पलेट और पैनल साइडबार लिंक अपने आप अपडेट हो जाएँगे।',
    'Portfolio Manager →' => 'पोर्टफ़ोलियो मैनेजर →',
    'Section / Category' => 'खंड / श्रेणी',
    'Display Name (Menu & Title)' => 'प्रदर्शित नाम (मेनू और शीर्षक)',
    'Page address' => 'पेज का पता',
    'Portfolio Name in Admin Menu' => 'एडमिन मेनू में पोर्टफ़ोलियो का नाम',
    'Shown only in the admin sidebar' => 'केवल एडमिन साइडबार में दिखता है',
    'Not shown on the site' => 'साइट पर नहीं दिखता',
    '2. Static Pages (Blog, About, Contact etc.)' => '2. स्थिर पेज (ब्लॉग, परिचय, संपर्क आदि)',
    'Rename pages to anything you like. The top menu updates automatically.' => 'पेजों का नाम अपनी पसंद से बदलें। शीर्ष मेनू अपने आप अपडेट हो जाता है।',
    'Page Type' => 'पेज प्रकार',
    'Homepage Root' => 'होमपेज रूट',
    'Image Converter' => 'इमेज कन्वर्टर',
    'Generates fast-loading AVIF and WebP versions and smaller sizes of uploaded photos.' => 'अपलोड की गई तस्वीरों के तेज़ लोड होने वाले AVIF और WebP संस्करण और छोटे आकार बनाता है।',
    'High Depth & Engagement' => 'उच्च गहराई और जुड़ाव',
    'Photo reading time' => 'तस्वीर देखने का समय',
    'Portfolio & Stories' => 'पोर्टफ़ोलियो और कहानियाँ',
    'Per user' => 'प्रति उपयोगकर्ता',
    'Unique visits' => 'अद्वितीय विज़िट',
    'Desktop (Editorial / Jury)' => 'डेस्कटॉप (संपादकीय / जूरी)',
    'Avg.' => 'औसत',
    'Curators, jury, and editors review on large displays' => 'क्यूरेटर, जूरी और संपादक बड़ी स्क्रीन पर समीक्षा करते हैं',
    'Large Display Review' => 'बड़ी स्क्रीन पर समीक्षा',
    'Mobile (Social Discovery)' => 'मोबाइल (सोशल खोज)',
    'Instagram & X Entrances' => 'Instagram और X से प्रवेश',
    'Views' => 'व्यू',
    'Unique' => 'अद्वितीय',
    'Share' => 'साझा करें',
    'GA4 Property ID' => 'GA4 प्रॉपर्टी ID',
    'The Property ID from your Google Analytics dashboard (e.g. <code>123456789</code>).' => 'आपके Google Analytics डैशबोर्ड की प्रॉपर्टी ID (उदा. <code>123456789</code>)।',
    'Google Cloud Service Account JSON Key' => 'Google Cloud सर्विस अकाउंट JSON कुंजी',
    'or select JSON file: ' => 'या JSON फ़ाइल चुनें: ',
    'Steps to Enable Live Data:' => 'लाइव डेटा सक्षम करने के चरण:',
